<script module lang="ts">
/**
 * AppShell.NavGroup: a labelled section of the rail.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/app-shell.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/archetypes/app-shell.module.css'

export interface AppShellNavGroupProps {
  /**
   * The section’s name, one or two words.
   */
  label: string
  /**
   * NavItems.
   */
  children: Snippet
}
</script>

<script lang="ts">
let { label: labelOwn, children }: AppShellNavGroupProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.navGroup} role="group" aria-label={label}
    ><span class={styles.navGroupLabel}>{label}</span
    >{@render children?.()
  }</div
>{/if
}{@render joined.end?.()}
